import json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'results/E7d_park_warp/2026-10-28/white_pointmaps';z=np.load(OUT/'pointmap_candidates.npz');a=z['source_xyz'];b=z['target_xyz'];ca=a.mean(0);cb=b.mean(0);aa=a-ca;bb=b-cb;u,s,v=np.linalg.svd(bb.T@aa/len(a));d=np.ones(3);d[-1]=np.linalg.det(u@v);r=u@np.diag(d)@v;scale=(s*d).sum()/np.mean(np.sum(aa*aa,axis=1));m=scale*(a-ca)@r.T+cb;center=b.mean(0);_,_,vh=np.linalg.svd(b-center,full_matrices=False);along=(b-center)@vh[0];normal_a=(m-center)@vh[-1];normal_b=(b-center)@vh[-1];hold=z['heldout_distance'];fig,axs=plt.subplots(1,2,figsize=(12,5),constrained_layout=True);axs[0].scatter(along,normal_a,s=24,c='#2563eb',label='0001, globally fitted Sim3',alpha=.75);axs[0].scatter(along,normal_b,s=24,c='#dc2626',label='0072',alpha=.75);axs[0].set(xlabel='target plane principal direction (local units)',ylabel='target plane normal coordinate (local units)',title='Same candidates after global similarity fit');axs[0].legend();axs[0].grid(alpha=.2);p=z['source_native_xy'];sc=axs[1].scatter(p[:,0],p[:,1],c=hold,s=50,cmap='viridis');axs[1].set_aspect('equal');axs[1].invert_yaxis();axs[1].set(xlabel='0001 source x (native pixels)',ylabel='0001 source y (native pixels)',title='Spatial holdout 3D distance');fig.colorbar(sc,ax=axs[1],label='target local units');fig.suptitle('MASt3R pair candidates: not external depth error; selection precedes holdout');fig.savefig(OUT/'pointmap_comparison.png',dpi=160)
